/* The tables of M13 · Syllabus and lesson plans. */

/** The syllabus as a tree: unit, chapter, topic. */
export const syllabusUnits = defineTable(
  'syllabus_units',
  { module: 'M13', scope: 'org', member: { read: { status: 'active' } } },
  {
    ...baseColumns,
    gradeSubjectId: uuid()
      .references((): AnyPgColumn => gradeSubjects.id)
      .notNull(),
    /** empty for a top-level unit */
    parentId: uuid().references((): AnyPgColumn => syllabusUnits.id),
    kind: enumText(syllabusUnitKinds).notNull(),
    /** the board's reference */
    code: text(),
    title: text().notNull(),
    titleUr: text(),
    description: text(),
    estimatedPeriods: integer().notNull().default(0),
    sortOrder: integer().notNull(),
    source: enumText(syllabusUnitSources).notNull().default('manual'),
    aiConfidence: decimal(4, 2),
    status: enumText(syllabusUnitStatuses).notNull().default('active'),
  },
  (t) => [
    nonNegative('syllabus_units', t.estimatedPeriods),
    between('syllabus_units', t.aiConfidence, 0, 1),
    index('syllabus_units_grade_subject_parent_sort_order_idx').on(
      t.orgId,
      t.gradeSubjectId,
      t.parentId,
      t.sortOrder,
    ),
  ],
);

/** Student learning outcomes (SLOs) under a topic. */
export const learningOutcomes = defineTable(
  'learning_outcomes',
  { module: 'M13', scope: 'org', member: 'read' },
  {
    ...baseColumns,
    unitId: uuid()
      .references((): AnyPgColumn => syllabusUnits.id)
      .notNull(),
    /** `P-09-A-03` */
    code: text(),
    statement: text().notNull(),
    statementUr: text(),
    level: enumText(learningOutcomeLevels),
    sortOrder: integer().notNull().default(0),
  },
);

/** The term plan for a subject in a grade. */
export const schemesOfWork = defineTable(
  'schemes_of_work',
  { module: 'M13', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    academicYearId: uuid()
      .references((): AnyPgColumn => academicYears.id)
      .notNull(),
    termId: uuid()
      .references((): AnyPgColumn => terms.id)
      .notNull(),
    gradeSubjectId: uuid()
      .references((): AnyPgColumn => gradeSubjects.id)
      .notNull(),
    /** empty means every section of the grade */
    sectionId: uuid().references((): AnyPgColumn => sections.id),
    status: enumText(schemesOfWorkStatuses).notNull().default('draft'),
    submittedBy: uuid().references((): AnyPgColumn => profiles.id),
    approvedBy: uuid().references((): AnyPgColumn => profiles.id),
    approvedAt: timestamptz(),
    returnNote: text(),
    draftedByAi: boolean().notNull().default(false),
  },
  (t) => [
    uniqueIndex('schemes_of_work_branch_term_grade_subject_section_uq')
      .on(
        t.branchId,
        t.termId,
        t.gradeSubjectId,
        sql`coalesce(${t.sectionId}, '00000000-0000-0000-0000-000000000000'::uuid)`,
      )
      .where(live(t)),
  ],
);

export const schemeWeeks = defineTable(
  'scheme_weeks',
  { module: 'M13', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    schemeId: uuid()
      .references((): AnyPgColumn => schemesOfWork.id)
      .notNull(),
    weekNo: integer().notNull(),
    startDate: dateStr().notNull(),
    endDate: dateStr().notNull(),
    /** topics planned for the week */
    unitIds: uuid()
      .array()
      .notNull()
      .default(sql`'{}'`),
    periodsPlanned: integer().notNull().default(0),
    activities: text(),
    assessment: text(),
    note: text(),
  },
  (t) => [
    positive('scheme_weeks', t.weekNo),
    check('scheme_weeks_end_date_from', sql`${t.endDate} >= ${t.startDate}`),
    nonNegative('scheme_weeks', t.periodsPlanned),
    uniqueIndex('scheme_weeks_scheme_week_no_uq').on(t.schemeId, t.weekNo).where(live(t)),
  ],
);

/** What a section has actually covered. */
export const syllabusProgress = defineTable(
  'syllabus_progress',
  { module: 'M13', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    sectionSubjectId: uuid()
      .references((): AnyPgColumn => sectionSubjects.id)
      .notNull(),
    /** a chapter or topic */
    unitId: uuid()
      .references((): AnyPgColumn => syllabusUnits.id)
      .notNull(),
    status: enumText(syllabusProgressStatuses).notNull().default('not_started'),
    startedOn: dateStr(),
    completedOn: dateStr(),
    periodsUsed: integer().notNull().default(0),
  },
  (t) => [
    check('syllabus_progress_completed_on_from', sql`${t.completedOn} >= ${t.startedOn}`),
    nonNegative('syllabus_progress', t.periodsUsed),
    uniqueIndex('syllabus_progress_section_subject_unit_uq')
      .on(t.sectionSubjectId, t.unitId)
      .where(live(t)),
  ],
);

